/// Canonical zero-hydrogen-variant series; chemistry is generated by mzannotate.
fn fragment_generation_model() -> FragmentationModel {
    // Theoretical fragment generation is decided by the fragmentation
    // method's own chemistry: ETD yields the plain c/z series (the
    // paper-tools convention), HCD/CID b/y. The z•/z′ hydrogen variants are
    // no longer generated; keeping the z series loss configuration intact is
    // why the model override stays.
    let model = FragmentationModel::all().clone();
    let z_series = model.z.clone().variants(vec![0]);
    model.z(z_series)
}

