pub struct MassModification {
    pub position: String,
    pub delta_mass: f64,
    /// Exact net elemental formula when the ProForma tag carries chemistry
    /// (for example `BrH-1` for bromination).  `None` is a deliberate
    /// mass-only hypothesis: it can match m/z, but cannot make isotope-shape
    /// claims.  Keeping this beside the delta prevents the CLI from erasing
    /// Br/Phospho chemistry before envelope matching.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub formula: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct NamedNeutralLoss {
    pub label: String,
    pub delta_mass: f64,
    /// Site the loss is chemically bound to: a 1-based residue index,
    /// `"nTerm"` or `"cTerm"` — the same convention as
    /// `MassModification::position`. Required: a modification-defined
    /// neutral loss is emitted only for fragments whose residue span
    /// contains this site (a c5 ion cannot lose H3PO4 from a phospho on
    /// residue 88). Accepts the index as a string or an integer.
    #[serde(default, deserialize_with = "deserialize_loss_position")]
    pub position: Option<String>,
}

/// `position` accepts `"88"` and `88` alike — callers write both forms.
fn deserialize_loss_position<'de, D>(deserializer: D) -> Result<Option<String>, D::Error>
where
    D: serde::Deserializer<'de>,
{
    struct PositionVisitor;
    impl serde::de::Visitor<'_> for PositionVisitor {
        type Value = Option<String>;
        fn expecting(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            formatter.write_str("a position (nTerm, cTerm, or a 1-based residue index)")
        }
        fn visit_none<E>(self) -> Result<Self::Value, E> {
            Ok(None)
        }
        fn visit_unit<E>(self) -> Result<Self::Value, E> {
            Ok(None)
        }
        fn visit_str<E>(self, value: &str) -> Result<Self::Value, E> {
            Ok(Some(value.to_owned()))
        }
        fn visit_u64<E>(self, value: u64) -> Result<Self::Value, E> {
            Ok(Some(value.to_string()))
        }
    }
    deserializer.deserialize_any(PositionVisitor)
}

/// Where a named neutral loss may occur, parsed once from
/// `NamedNeutralLoss::position` before fragment generation.
#[derive(Debug, Clone, Copy, PartialEq)]
enum LossSite {
    NTerm,
    CTerm,
    Residue(usize),
}

fn parse_loss_site(loss: &NamedNeutralLoss) -> Result<LossSite, MassSpecError> {
    let Some(position) = loss.position.as_deref() else {
        return Err(MassSpecError::InvalidQuery(
            "neutralLosses require a position (residue index, nTerm, or cTerm): the loss is \
             emitted only for fragments whose residue span contains that site"
                .to_owned(),
        ));
    };
    match position {
        "nTerm" => Ok(LossSite::NTerm),
        "cTerm" => Ok(LossSite::CTerm),
        value => {
            let index = value.parse::<usize>().map_err(|_| {
                MassSpecError::InvalidQuery(format!(
                    "neutralLoss position must be a residue index, nTerm, or cTerm; got {value:?}"
                ))
            })?;
            if index == 0 {
                return Err(MassSpecError::InvalidQuery(
                    "neutralLoss position is 1-based; got 0".to_owned(),
                ));
            }
            Ok(LossSite::Residue(index))
        }
    }
}

/// Does the fragment `mapped`/`number` (series_number counts residues from its
/// own terminus) contain `site`? N-terminal ions (a/b/c) span residues
/// `1..=number`; C-terminal ions (x/y/z, z•, z′) span
/// `sequence_length - number + 1..=sequence_length`.
fn span_contains_site(
    mapped: IonType,
    number: usize,
    sequence_length: usize,
    site: LossSite,
) -> bool {
    let n_terminal = matches!(mapped, IonType::A | IonType::B | IonType::C);
    match site {
        LossSite::NTerm => n_terminal,
        LossSite::CTerm => !n_terminal,
        LossSite::Residue(index) => {
            if n_terminal {
                index <= number
            } else {
                index + number > sequence_length
            }
        }
    }
}

/// Raw-mzML fragment matching runs one route only: exact-envelope matching.
/// Each fragment keeps its chemical isotope shape, requires the theoretical
/// apex, walks neighboring isotope positions with Informed-Proteomics'
/// monotone cursor, and scores missing positions as zero in the full-envelope
/// Pearson. Accepted cells use LCMS-Spectator's most-intense-observed-isotope
/// display rule. Rejected theoretical charge states remain visible in
/// `fragment_statuses`. A monoisotopic single-peak matcher cannot see a
/// top-down fragment whose apex sits at M+k, so it is not offered.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FragmentMatchQuery {
    pub selector: SpectrumSelector,
    pub sequence: String,
    #[serde(default)]
    pub modifications: Vec<MassModification>,
    pub ion_types: Vec<IonType>,
    pub max_charge: u8,
    pub tolerance_ppm: f64,
    pub min_intensity: Option<f32>,
    pub max_matches: Option<usize>,
    #[serde(default)]
    pub neutral_losses: Vec<NamedNeutralLoss>,
    /// Emit the fragmentation engine's own chemically-gated loss variants
    /// (standard series losses such as H2O, plus modification-specific losses
    /// when the proforma modification carries loss definitions). Off by
    /// default: recorded no-loss runs must stay reproducible.
    #[serde(default)]
    pub engine_neutral_losses: bool,
    /// Pearson threshold for envelope matching (Spectator
    /// IonCorrelationThreshold default 0.7).
    #[serde(default = "default_min_correlation")]
    pub min_correlation: f64,
}

fn default_min_correlation() -> f64 {
    0.7
}

