#[derive(Debug, Clone)]
pub struct TheoreticalFragment {
    pub ion: IonType,
    pub number: usize,
    pub charge: u8,
    pub cleavage_after: usize,
    pub neutral_mass: f64,
    pub mz: f64,
    /// The m/z of the fragment's *most abundant* isotopologue (the apex),
    /// computed from its exact composition through the crate's single BRAIN
    /// envelope kernel (`theory::theoretical_envelope`). For a fragment large
    /// enough that M0 falls below the noise, this is the channel the spectrum
    /// actually populates — the fragment-level analogue of the MS1 feature-mass
    /// apex anchor (Predator Protein Fragment Calculator's rationale, MCP 2024).
    pub apex_mz: f64,
    /// How many neutrons the apex sits above the monoisotopic peak (0 = M0).
    /// Neutral-frame, so it is valid across charge states.
    pub apex_offset: usize,
    /// The full BRAIN isotope envelope (per-isotopologue m/z + apex-normalized
    /// relative intensity), from the same single kernel that produced `apex_mz`.
    /// Empty when the envelope was not requested (matching hot paths, mzPAF /
    /// mzTab interchange, or `--no-envelope`).
    pub isotope_envelope: Vec<IsotopeEnvelopePeak>,
    pub neutral_loss: Option<String>,
}

/// Resolve a spectrum selector that names a bare scan number (`Id("scan=1164")`)
/// to the file's full nativeID (which may carry a controller prefix like
/// `controllerType=0 controllerNumber=1 scan=1164`). Exact ids pass through.
#[cfg(test)]
pub(crate) fn resolve_selector(
    bytes: &[u8],
    selector: &SpectrumSelector,
) -> Result<SpectrumSelector, MassSpecError> {
    let mut reader = open_reader(bytes)?;
    resolve_selector_from_reader(&mut reader, selector)
}

/// Same resolution, but on an already-open reader (no re-parse).
pub(crate) fn resolve_selector_from_reader(
    reader: &mut Reader,
    selector: &SpectrumSelector,
) -> Result<SpectrumSelector, MassSpecError> {
    let SpectrumSelector::Id(id) = selector else {
        return Ok(selector.clone());
    };
    let Some(tail) = id.strip_prefix("scan=") else {
        return Ok(selector.clone()); // not a scan-number form; pass through
    };
    if !tail.chars().all(|c| c.is_ascii_digit()) {
        return Ok(selector.clone());
    }
    if reader
        .get_index()
        .iter()
        .any(|(native, _)| native.as_ref() == id.as_str())
    {
        return Ok(selector.clone());
    }
    let mut resolved = None;
    for (native, _) in reader.get_index().iter() {
        if crate::mzml::scan_token(native).as_deref() == Some(tail) {
            if resolved.is_some() {
                return Err(MassSpecError::InvalidQuery(format!(
                    "ambiguous scan number {tail}; use the full nativeID"
                )));
            }
            resolved = Some(native.to_string());
        }
    }
    Ok(resolved
        .map(SpectrumSelector::Id)
        .unwrap_or_else(|| selector.clone()))
}

pub fn query_fragment_match_mzml(
    bytes: &[u8],
    query: &FragmentMatchQuery,
) -> Result<FragmentMatchResult, MassSpecError> {
    let mut reader = open_reader(bytes)?;
    query_fragment_match_reader(&mut reader, query)
}

/// Read source activation without decoding peaks or opening another reader.
pub fn fragment_activation(
    reader: &mut Reader,
    selector: &SpectrumSelector,
) -> Result<Option<String>, MassSpecError> {
    let selector = resolve_selector_from_reader(reader, selector)?;
    let detail = *reader.detail_level();
    reader.set_detail_level(mzdata::io::DetailLevel::MetadataOnly);
    let spectrum = match &selector {
        SpectrumSelector::Index(index) => reader.get_spectrum_by_index(*index),
        SpectrumSelector::Id(id) => reader.get_spectrum_by_id(id),
    };
    reader.set_detail_level(detail);
    let spectrum =
        spectrum.ok_or_else(|| MassSpecError::SpectrumNotFound(format!("{selector:?}")))?;
    Ok(spectrum
        .precursor()
        .and_then(|p| p.activation.method())
        .map(|method| method.name().to_owned()))
}

/// The precursor's declared charge state for one scan — the physical ceiling
/// for fragment charges (a fragment cannot carry more charge than its
/// precursor). Metadata-only read; None when the acquisition declares none.
pub fn fragment_precursor_charge(
    reader: &mut Reader,
    selector: &SpectrumSelector,
) -> Result<Option<u8>, MassSpecError> {
    let selector = resolve_selector_from_reader(reader, selector)?;
    let detail = *reader.detail_level();
    reader.set_detail_level(mzdata::io::DetailLevel::MetadataOnly);
    let spectrum = match &selector {
        SpectrumSelector::Index(index) => reader.get_spectrum_by_index(*index),
        SpectrumSelector::Id(id) => reader.get_spectrum_by_id(id),
    };
    reader.set_detail_level(detail);
    let spectrum =
        spectrum.ok_or_else(|| MassSpecError::SpectrumNotFound(format!("{selector:?}")))?;
    Ok(spectrum
        .precursor()
        .and_then(|p| {
            p.ions
                .iter()
                .filter_map(|ion| ion.charge)
                .map(i32::unsigned_abs)
                .max()
        })
        .and_then(|z| u8::try_from(z).ok()))
}

/// Select the chemically appropriate fragment series from acquisition metadata.
/// This belongs in the core so every caller (CLI, Python adapter, UI) gets the
/// same ETD/ECD -> c/z and HCD/CID -> b/y rule.
pub fn ion_types_for_activation(activation: Option<&str>) -> Result<Vec<IonType>, MassSpecError> {
    let value = activation.unwrap_or_default().to_ascii_lowercase();
    if matches!(value.as_str(), "etd" | "ecd")
        || value.contains("electron transfer")
        || value.contains("electron capture")
    {
        return Ok(vec![IonType::C, IonType::Z]);
    }
    if matches!(value.as_str(), "hcd" | "cid")
        || value.contains("collision-induced")
        || value.contains("higher-energy")
    {
        return Ok(vec![IonType::B, IonType::Y]);
    }
    Err(MassSpecError::InvalidQuery(
        "fragment ion series could not be inferred from activation; pass --ion-types explicitly (ETD/ECD: C,Z; HCD/CID: B,Y)".to_owned(),
    ))
}

/// Reader-resident variant: callers that deliberately evaluate several models
/// on one spectrum may reuse one mzML reader. Same semantics as the bytes entry.
pub fn query_fragment_match_reader(
    reader: &mut Reader,
    query: &FragmentMatchQuery,
) -> Result<FragmentMatchResult, MassSpecError> {
    validate_query(query)?;
    let selector = resolve_selector_from_reader(reader, &query.selector)?;
    let peaks = fragment_observations(reader, &selector, query.min_intensity)?;
    match_observed_fragments(query, &peaks)
}

fn fragment_observations(
    reader: &mut Reader,
    selector: &SpectrumSelector,
    min_intensity: Option<f32>,
) -> Result<Vec<Peak>, MassSpecError> {
    let observation = crate::extract_spectrum_observation_reader(
        reader,
        std::slice::from_ref(selector),
        None,
        0.0,
    )?;
    observation.fragment_activation(None)?;
    Ok(observation
        .peaks
        .into_iter()
        .filter(|peak| min_intensity.is_none_or(|minimum| peak.intensity >= minimum))
        .collect())
}

/// Match an extracted/pool observation without reopening its original mzML.
/// Indices refer to the observation's peak list after the query intensity filter.
pub fn query_fragment_match_observation(
    observation: &crate::SpectrumObservation,
    query: &FragmentMatchQuery,
    activation: Option<&str>,
) -> Result<FragmentMatchResult, MassSpecError> {
    PreparedFragmentMatch::new(query)?.match_observation(observation, activation)
}

pub fn query_candidate_comparison_observation(
    observation: &crate::SpectrumObservation,
    query: &CandidateComparisonQuery,
    activation: Option<&str>,
) -> Result<CandidateComparisonResult, MassSpecError> {
    PreparedCandidateComparison::new(query)?.match_observation(observation, activation)
}

/// Immutable theory and matching settings, reusable across observations.
/// Preparation validates the model before any observation is matched.
pub struct PreparedFragmentMatch {
    query: FragmentMatchQuery,
    neutral_mass: f64,
    fragments: Vec<TheoreticalFragment>,
}

impl PreparedFragmentMatch {
    pub fn new(query: &FragmentMatchQuery) -> Result<Self, MassSpecError> {
        validate_query(query)?;
        let (neutral_mass, fragments) = fragment_theory(query)?;
        Ok(Self {
            query: query.clone(),
            neutral_mass,
            fragments,
        })
    }

    pub fn match_observation(
        &self,
        observation: &crate::SpectrumObservation,
        activation: Option<&str>,
    ) -> Result<FragmentMatchResult, MassSpecError> {
        observation.fragment_activation(activation)?;
        let peaks = observation.selected_peaks(self.query.min_intensity);
        self.match_peaks(&peaks)
    }

    fn match_peaks(&self, peaks: &[Peak]) -> Result<FragmentMatchResult, MassSpecError> {
        match_observed_fragments_prepared(&self.query, peaks, self.neutral_mass, &self.fragments)
    }

    pub fn match_deconvoluted(
        &self,
        spectrum: &crate::MsAlignSpectrum,
    ) -> Result<FragmentMatchResult, MassSpecError> {
        match_deconvoluted_prepared(spectrum, &self.query, self.neutral_mass, &self.fragments)
    }
}

/// A complete candidate set prepared once for a shared ion series and charge
/// ceiling. Observations stay external and may be raw or deconvoluted.
pub struct PreparedCandidateComparison {
    query: CandidateComparisonQuery,
    models: Vec<PreparedFragmentMatch>,
}

impl PreparedCandidateComparison {
    pub fn new(query: &CandidateComparisonQuery) -> Result<Self, MassSpecError> {
        if query.candidate_models.is_empty() || query.max_matches == Some(0) {
            return Err(MassSpecError::InvalidQuery(
                "nonempty candidates and a positive optional maxMatches are required".into(),
            ));
        }
        let mut ids = HashSet::new();
        let queries: Vec<_> = query
            .candidate_models
            .iter()
            .map(|model| {
                if model.id.trim().is_empty() || !ids.insert(&model.id) {
                    return Err(MassSpecError::InvalidQuery(
                        "candidate ids must be nonempty and unique".into(),
                    ));
                }
                let query = FragmentMatchQuery {
                    selector: query.selector.clone(),
                    sequence: model
                        .sequence
                        .clone()
                        .unwrap_or_else(|| query.sequence.clone()),
                    modifications: model.modifications.clone(),
                    ion_types: query.ion_types.clone(),
                    max_charge: query.max_charge,
                    tolerance_ppm: query.tolerance_ppm,
                    min_correlation: query.min_correlation,
                    min_intensity: query.min_intensity,
                    max_matches: None,
                    neutral_losses: query.neutral_losses.clone(),
                    engine_neutral_losses: query.engine_neutral_losses,
                };
                validate_query(&query)?;
                Ok(query)
            })
            .collect::<Result<_, MassSpecError>>()?;
        // All cheap checks finish before generating the first isotope envelope.
        let models = queries
            .iter()
            .map(PreparedFragmentMatch::new)
            .collect::<Result<_, _>>()?;
        Ok(Self {
            query: query.clone(),
            models,
        })
    }

    pub fn match_observation(
        &self,
        observation: &crate::SpectrumObservation,
        activation: Option<&str>,
    ) -> Result<CandidateComparisonResult, MassSpecError> {
        observation.fragment_activation(activation)?;
        let peaks = observation.selected_peaks(self.query.min_intensity);
        self.measure(
            "isotope_envelope_matching_with_shared_peak_indices",
            |model| model.match_peaks(&peaks),
        )
    }

    pub fn match_deconvoluted(
        &self,
        spectrum: &crate::MsAlignSpectrum,
    ) -> Result<CandidateComparisonResult, MassSpecError> {
        self.measure("deconvoluted_neutral_mass_matching", |model| {
            model.match_deconvoluted(spectrum)
        })
    }

    fn measure(
        &self,
        strategy: &str,
        mut measure: impl FnMut(&PreparedFragmentMatch) -> Result<FragmentMatchResult, MassSpecError>,
    ) -> Result<CandidateComparisonResult, MassSpecError> {
        let mut models = self.models.iter();
        compare_fragment_models(&self.query, strategy, |_| {
            measure(models.next().ok_or_else(|| {
                MassSpecError::InvalidQuery("prepared candidate count mismatch".into())
            })?)
        })
    }
}

fn match_observed_fragments(
    query: &FragmentMatchQuery,
    peaks: &[Peak],
) -> Result<FragmentMatchResult, MassSpecError> {
    PreparedFragmentMatch::new(query)?.match_peaks(peaks)
}

fn match_observed_fragments_prepared(
    query: &FragmentMatchQuery,
    peaks: &[Peak],
    theoretical_neutral_mass: f64,
    theoretical: &[TheoreticalFragment],
) -> Result<FragmentMatchResult, MassSpecError> {
    let sequence = query.sequence.trim().to_ascii_uppercase();
    let (mut matches, fragment_statuses) = match_fragments_envelope_with_status(
        theoretical,
        peaks,
        query.tolerance_ppm,
        query.min_correlation,
    );
    matches.sort_by(|left, right| {
        left.ion
            .cmp(&right.ion)
            .then(left.number.cmp(&right.number))
            .then(left.charge.cmp(&right.charge))
    });
    let summary = summarize(sequence.len(), &query.ion_types, &matches);
    let (per_series_error, series_divergence) = series_error_stats(&matches);
    let matched_peaks: HashSet<usize> = matches
        .iter()
        .flat_map(|matched| {
            matched
                .quantification
                .as_ref()
                .map(|q| q.observed_peak_indices.clone())
                .unwrap_or_else(|| vec![matched.observed_peak_index])
        })
        .collect();
    let mut unmatched: Vec<Peak> = peaks
        .iter()
        .enumerate()
        .filter(|(index, _)| !matched_peaks.contains(index))
        .map(|(_, peak)| *peak)
        .collect();
    unmatched.sort_unstable_by(|left, right| right.intensity.total_cmp(&left.intensity));
    let unmatched_peak_count = unmatched.len();
    unmatched.truncate(10);

    let total_matches = matches.len();
    if let Some(limit) = query.max_matches {
        matches.truncate(limit);
    }
    Ok(FragmentMatchResult {
        sequence,
        mass_table: "Unimod-compatible monoisotopic residue masses v1".to_owned(),
        theoretical_neutral_mass,
        theoretical_fragment_count: theoretical.len(),
        summary,
        per_series_error,
        series_divergence,
        matches,
        fragment_statuses,
        matches_truncated: query.max_matches.is_some_and(|limit| total_matches > limit),
        top_unmatched_peaks: unmatched,
        unmatched_peak_count,
    })
}

/// Fragment matching against a TopFD `_ms2.msalign` deconvoluted MS2 scan —
/// a DIFFERENT observation domain from the raw-mzML error map, not a
/// variant of it. TopFD has already collapsed every isotope envelope, so one
/// peak is one (neutral monoisotopic mass, charge, intensity) observation;
/// matching is a charge-aware one-to-one assignment in neutral-mass space.
/// Few peaks result, which is what makes the polyline-sequence / error-dot
/// figure readable — the figure this surface feeds must not be the heatmap.
pub fn query_fragment_match_msalign(
    bytes: &[u8],
    query: &FragmentMatchQuery,
) -> Result<FragmentMatchResult, MassSpecError> {
    validate_query(query)?;
    let scan = match &query.selector {
        SpectrumSelector::Id(id) => id.strip_prefix("scan=").unwrap_or(id).to_owned(),
        SpectrumSelector::Index(index) => index.to_string(),
    };
    let spectrum = crate::localize::parse_msalign_spectrum(bytes, &scan)?;
    query_fragment_match_deconvoluted(&spectrum, query)
}

pub fn query_fragment_match_deconvoluted(
    spectrum: &crate::MsAlignSpectrum,
    query: &FragmentMatchQuery,
) -> Result<FragmentMatchResult, MassSpecError> {
    PreparedFragmentMatch::new(query)?.match_deconvoluted(spectrum)
}

fn match_deconvoluted_prepared(
    spectrum: &crate::MsAlignSpectrum,
    query: &FragmentMatchQuery,
    theoretical_neutral_mass: f64,
    theoretical: &[TheoreticalFragment],
) -> Result<FragmentMatchResult, MassSpecError> {
    let sequence = query.sequence.trim().to_ascii_uppercase();
    let (mut matches, fragment_statuses) = match_fragments_msalign(
        theoretical,
        &spectrum.peaks,
        query.tolerance_ppm,
        query.min_intensity,
    );
    matches.sort_by(|left, right| {
        left.ion
            .cmp(&right.ion)
            .then(left.number.cmp(&right.number))
            .then(left.charge.cmp(&right.charge))
    });
    let summary = summarize(sequence.len(), &query.ion_types, &matches);
    let (per_series_error, series_divergence) = series_error_stats(&matches);
    let matched_peaks: HashSet<usize> = matches
        .iter()
        .map(|matched| matched.observed_peak_index)
        .collect();
    let mut unmatched: Vec<Peak> = spectrum
        .peaks
        .iter()
        .enumerate()
        .filter(|(index, _)| !matched_peaks.contains(index))
        .map(|(_, peak)| {
            let charge = f64::from(peak.charge.unwrap_or(1).max(1));
            Peak {
                mz: (peak.mass + charge * PROTON) / charge,
                intensity: peak.intensity,
            }
        })
        .collect();
    unmatched.sort_unstable_by(|left, right| right.intensity.total_cmp(&left.intensity));
    let unmatched_peak_count = unmatched.len();
    unmatched.truncate(10);

    let total_matches = matches.len();
    if let Some(limit) = query.max_matches {
        matches.truncate(limit);
    }
    Ok(FragmentMatchResult {
        sequence,
        mass_table: "Unimod-compatible monoisotopic residue masses v1".to_owned(),
        theoretical_neutral_mass,
        theoretical_fragment_count: theoretical.len(),
        summary,
        per_series_error,
        series_divergence,
        matches,
        fragment_statuses,
        matches_truncated: query.max_matches.is_some_and(|limit| total_matches > limit),
        top_unmatched_peaks: unmatched,
        unmatched_peak_count,
    })
}

/// Kuhn's augmenting-path step for the maximum-cardinality one-to-one
/// peak assignment used by the msalign deconvoluted matcher.
fn augment_fragment(
    fragment_index: usize,
    edges: &[Vec<usize>],
    peak_owner: &mut [Option<usize>],
    seen_peaks: &mut [bool],
) -> bool {
    for &peak_index in &edges[fragment_index] {
        if seen_peaks[peak_index] {
            continue;
        }
        seen_peaks[peak_index] = true;
        let owner = peak_owner[peak_index];
        match owner {
            None => {
                peak_owner[peak_index] = Some(fragment_index);
                return true;
            }
            Some(previous_fragment)
                if augment_fragment(previous_fragment, edges, peak_owner, seen_peaks) =>
            {
                peak_owner[peak_index] = Some(fragment_index);
                return true;
            }
            Some(_) => {}
        }
    }
    false
}

/// Charge-aware one-to-one assignment in neutral-mass space: a deconvoluted
/// peak of charge z may only support a theoretical fragment of the same
/// charge whose neutral mass falls inside the ppm window. Maximum-cardinality
/// assignment keeps one peak one observation.
fn match_fragments_msalign(
    fragments: &[TheoreticalFragment],
    peaks: &[crate::localize::DeconvolutedPeak],
    tolerance_ppm: f64,
    min_intensity: Option<f32>,
) -> (Vec<FragmentMatch>, Vec<FragmentMatchStatus>) {
    let mut by_charge: BTreeMap<u8, Vec<usize>> = BTreeMap::new();
    for (index, peak) in peaks.iter().enumerate() {
        if let Some(charge) = peak.charge {
            if min_intensity.is_none_or(|minimum| peak.intensity >= minimum) {
                by_charge.entry(charge).or_default().push(index);
            }
        }
    }
    for list in by_charge.values_mut() {
        list.sort_unstable_by(|left, right| peaks[*left].mass.total_cmp(&peaks[*right].mass));
    }
    let mut edges: Vec<Vec<usize>> = Vec::with_capacity(fragments.len());
    for fragment in fragments {
        let window = fragment.neutral_mass * tolerance_ppm / 1_000_000.0;
        let mut candidates: Vec<usize> = by_charge
            .get(&fragment.charge)
            .map(|list| {
                list.iter()
                    .copied()
                    .filter(|index| (peaks[*index].mass - fragment.neutral_mass).abs() <= window)
                    .collect()
            })
            .unwrap_or_default();
        candidates.sort_by(|left, right| {
            let left_error = (peaks[*left].mass - fragment.neutral_mass).abs();
            let right_error = (peaks[*right].mass - fragment.neutral_mass).abs();
            left_error
                .total_cmp(&right_error)
                .then_with(|| peaks[*right].intensity.total_cmp(&peaks[*left].intensity))
                .then(left.cmp(right))
        });
        edges.push(candidates);
    }
    let mut order: Vec<usize> = (0..fragments.len()).collect();
    order.sort_by(|left, right| {
        edges[*left]
            .len()
            .cmp(&edges[*right].len())
            .then_with(|| fragments[*left].mz.total_cmp(&fragments[*right].mz))
            .then(left.cmp(right))
    });
    let mut peak_owner: Vec<Option<usize>> = vec![None; peaks.len()];
    for fragment_index in order {
        let mut seen_peaks = vec![false; peaks.len()];
        let _ = augment_fragment(fragment_index, &edges, &mut peak_owner, &mut seen_peaks);
    }
    let mut assigned = vec![None; fragments.len()];
    for (peak_index, fragment_index) in peak_owner.into_iter().enumerate() {
        if let Some(fragment_index) = fragment_index {
            assigned[fragment_index] = Some(peak_index);
        }
    }
    let mut matches = Vec::new();
    let mut statuses = Vec::new();
    for (fragment_index, fragment) in fragments.iter().enumerate() {
        match assigned[fragment_index] {
            Some(peak_index) => {
                let peak = &peaks[peak_index];
                let charge = f64::from(fragment.charge);
                matches.push(FragmentMatch {
                    ion: fragment.ion,
                    number: fragment.number,
                    charge: fragment.charge,
                    cleavage_after: fragment.cleavage_after,
                    neutral_mass: fragment.neutral_mass,
                    theoretical_mz: fragment.mz,
                    theoretical_apex_mz: fragment.apex_mz,
                    apex_offset: fragment.apex_offset,
                    observed_isotope_offset: 0,
                    observed_mz: (peak.mass + charge * PROTON) / charge,
                    observed_neutral_mass: peak.mass,
                    observed_peak_index: peak_index,
                    intensity: peak.intensity,
                    quantification: None,
                    envelope_correlation: None,
                    error_ppm: (peak.mass - fragment.neutral_mass) / fragment.neutral_mass
                        * 1_000_000.0,
                    neutral_loss: fragment.neutral_loss.clone(),
                });
            }
            None => statuses.push(FragmentMatchStatus {
                ion: fragment.ion,
                number: fragment.number,
                charge: fragment.charge,
                cleavage_after: fragment.cleavage_after,
                theoretical_mz: fragment.mz,
                theoretical_apex_mz: fragment.apex_mz,
                apex_offset: fragment.apex_offset,
                state: FragmentMatchState::MissingPeak,
                envelope_correlation: None,
            }),
        }
    }
    (matches, statuses)
}

pub fn query_candidate_comparison_mzml(
    bytes: &[u8],
    query: &CandidateComparisonQuery,
) -> Result<CandidateComparisonResult, MassSpecError> {
    let mut reader = open_reader(bytes)?;
    query_candidate_comparison_reader(&mut reader, query)
}

/// Reader-resident variant for candidate comparison (open once, query many).
pub fn query_candidate_comparison_reader(
    reader: &mut Reader,
    query: &CandidateComparisonQuery,
) -> Result<CandidateComparisonResult, MassSpecError> {
    let selector = resolve_selector_from_reader(reader, &query.selector)?;
    let peaks = fragment_observations(reader, &selector, query.min_intensity)?;
    compare_observed_fragments(query, &peaks)
}

/// Sum a declared homogeneous MS2 pool before envelope admission, retaining
/// the exact peak list used by all candidates for quantitative auditing.
pub fn query_candidate_comparison_sum_reader(
    reader: &mut Reader,
    query: &CandidateComparisonQuery,
    selectors: &[SpectrumSelector],
    bin_ppm: f64,
    minimum_abundance_pct: f64,
) -> Result<(CandidateComparisonResult, Vec<Peak>), MassSpecError> {
    let observation = crate::extract_spectrum_observation_reader(
        reader,
        selectors,
        Some(bin_ppm),
        minimum_abundance_pct,
    )?;
    let result = query_candidate_comparison_observation(&observation, query, None)?;
    let peaks = observation
        .peaks
        .into_iter()
        .filter(|p| {
            query
                .min_intensity
                .is_none_or(|minimum| p.intensity >= minimum)
        })
        .collect();
    Ok((result, peaks))
}

fn compare_observed_fragments(
    query: &CandidateComparisonQuery,
    peaks: &[Peak],
) -> Result<CandidateComparisonResult, MassSpecError> {
    PreparedCandidateComparison::new(query)?.measure(
        "isotope_envelope_matching_with_shared_peak_indices",
        |model| model.match_peaks(peaks),
    )
}

pub fn query_candidate_comparison_msalign(
    bytes: &[u8],
    query: &CandidateComparisonQuery,
) -> Result<CandidateComparisonResult, MassSpecError> {
    let scan = match &query.selector {
        SpectrumSelector::Id(id) => id.strip_prefix("scan=").unwrap_or(id).to_owned(),
        SpectrumSelector::Index(index) => index.to_string(),
    };
    let spectrum = crate::parse_msalign_spectrum(bytes, &scan)?;
    query_candidate_comparison_deconvoluted(&spectrum, query)
}

pub fn query_candidate_comparison_deconvoluted(
    spectrum: &crate::MsAlignSpectrum,
    query: &CandidateComparisonQuery,
) -> Result<CandidateComparisonResult, MassSpecError> {
    PreparedCandidateComparison::new(query)?.match_deconvoluted(spectrum)
}

fn compare_fragment_models(
    query: &CandidateComparisonQuery,
    matching_strategy: &str,
    mut measure: impl FnMut(&FragmentMatchQuery) -> Result<FragmentMatchResult, MassSpecError>,
) -> Result<CandidateComparisonResult, MassSpecError> {
    let selector = query.selector.clone();
    if query.max_matches == Some(0) {
        return Err(MassSpecError::InvalidQuery(
            "maxMatches must be positive".into(),
        ));
    }
    if query.candidate_models.is_empty() {
        return Err(MassSpecError::InvalidQuery(
            "candidate comparison requires at least one complete model".to_owned(),
        ));
    }
    let models = query.candidate_models.clone();
    let sequences: Vec<_> = models
        .iter()
        .map(|model| {
            model
                .sequence
                .as_deref()
                .unwrap_or(&query.sequence)
                .trim()
                .to_ascii_uppercase()
        })
        .collect();
    let shared_backbone = sequences.iter().all(|seq| seq == &sequences[0]);
    let sequence = shared_backbone.then(|| sequences[0].clone());
    let ion_comparison_available =
        shared_backbone && query.neutral_losses.is_empty() && !query.engine_neutral_losses;
    let mut seen = BTreeSet::new();
    let mut results = Vec::with_capacity(models.len());
    let mut match_sets = Vec::with_capacity(models.len());
    for (model, model_sequence) in models.iter().zip(&sequences) {
        if model.id.trim().is_empty() || !seen.insert(model.id.clone()) {
            return Err(MassSpecError::InvalidQuery(format!(
                "duplicate candidate model id {}",
                model.id
            )));
        }
        let result = measure(&FragmentMatchQuery {
            selector: selector.clone(),
            sequence: model_sequence.clone(),
            modifications: model.modifications.clone(),
            ion_types: query.ion_types.clone(),
            max_charge: query.max_charge,
            tolerance_ppm: query.tolerance_ppm,
            min_intensity: query.min_intensity,
            max_matches: None,
            neutral_losses: query.neutral_losses.clone(),
            engine_neutral_losses: query.engine_neutral_losses,
            min_correlation: query.min_correlation,
        })?;
        let keys: BTreeSet<_> = result
            .matches
            .iter()
            .map(|matched| (matched.ion, matched.number, matched.charge))
            .collect();
        results.push(CandidateFragmentSummary {
            candidate_id: model.id.clone(),
            sequence: model_sequence.clone(),
            theoretical_neutral_mass: result.theoretical_neutral_mass,
            modifications: model.modifications.clone(),
            matched_ions: result.summary.matched_ions,
            matched_intensity: result.summary.matched_intensity,
            coverage: result.summary.coverage,
            per_ion_type: result.summary.per_ion_type,
            discriminating_matched: 0,
            median_abs_error_ppm: error_quantile(&result.matches, 0.50),
            p95_abs_error_ppm: error_quantile(&result.matches, 0.95),
            unique_cleavages: result.summary.bonds_covered,
            site_window: site_window_evidence(&model.modifications, &result.matches),
            matches: result.matches,
            matches_truncated: false,
            fragment_statuses: result.fragment_statuses,
            series_divergence: result.series_divergence,
        });
        match_sets.push(keys);
    }

    let all_keys: BTreeSet<_> = if ion_comparison_available {
        match_sets.iter().flatten().copied().collect()
    } else {
        BTreeSet::new()
    };
    let mut discriminating_ions = Vec::new();
    for (ion, number, charge) in all_keys {
        let matched_candidates: Vec<_> = match_sets
            .iter()
            .enumerate()
            .filter(|(_, keys)| keys.contains(&(ion, number, charge)))
            .map(|(index, _)| models[index].id.clone())
            .collect();
        if matched_candidates.len() == models.len() {
            continue;
        }
        for (index, candidate) in models.iter().enumerate() {
            let candidate = &candidate.id;
            if matched_candidates.contains(candidate) {
                results[index].discriminating_matched += 1;
            }
        }
        discriminating_ions.push(DiscriminatingIon {
            ion,
            number,
            charge,
            matched_candidates,
        });
    }

    let per_candidate_matches: Vec<&[FragmentMatch]> =
        results.iter().map(|r| r.matches.as_slice()).collect();
    let isotope_borrow_pairs = if shared_backbone && matching_strategy.starts_with("isotope_") {
        detect_isotope_borrow_pairs(&models, &per_candidate_matches, query.tolerance_ppm)
    } else {
        Vec::new()
    };

    // Limit the exported table only after all measurements and diagnostics.
    if let Some(limit) = query.max_matches {
        for result in &mut results {
            result.matches_truncated = result.matches.len() > limit;
            result.matches.truncate(limit);
        }
    }
    Ok(CandidateComparisonResult {
        sequence,
        shared_backbone,
        ion_comparison_available,
        mass_table: "Unimod-compatible monoisotopic residue masses v1".to_owned(),
        candidate_models: models,
        matching_strategy: matching_strategy.to_owned(),
        discriminating_ion_count: discriminating_ions.len(),
        discriminating_ions,
        isotope_borrow_pairs,
        candidates: results,
    })
}

fn validate_query(query: &FragmentMatchQuery) -> Result<(), MassSpecError> {
    if query.sequence.trim().len() < 2 {
        return Err(MassSpecError::InvalidQuery(
            "fragmentMatch sequence must contain at least two residues".to_owned(),
        ));
    }
    if query.ion_types.is_empty() || query.max_charge == 0 {
        return Err(MassSpecError::InvalidQuery(
            "fragmentMatch requires ionTypes and a positive maxCharge".to_owned(),
        ));
    }
    validate_fragment_parameters(
        Some(query.max_charge),
        query.tolerance_ppm,
        query.min_correlation,
        query.min_intensity,
        query.max_matches,
    )?;
    for loss in &query.neutral_losses {
        if loss.label.trim().is_empty() || !loss.delta_mass.is_finite() || loss.delta_mass <= 0.0 {
            return Err(MassSpecError::InvalidQuery(
                "fragmentMatch neutralLosses require a label and positive deltaMass".to_owned(),
            ));
        }
        if let LossSite::Residue(position) = parse_loss_site(loss)? {
            if position > query.sequence.trim().len() {
                return Err(MassSpecError::InvalidQuery(format!(
                    "neutralLoss position {position} exceeds the model sequence"
                )));
            }
        }
    }
    Ok(())
}

pub fn validate_fragment_parameters(
    max_charge: Option<u8>,
    tolerance_ppm: f64,
    min_correlation: f64,
    min_intensity: Option<f32>,
    max_matches: Option<usize>,
) -> Result<(), MassSpecError> {
    if max_charge == Some(0)
        || max_matches == Some(0)
        || !tolerance_ppm.is_finite()
        || tolerance_ppm <= 0.0
        || !min_correlation.is_finite()
        || !(-1.0..=1.0).contains(&min_correlation)
        || min_intensity.is_some_and(|v| !v.is_finite() || v < 0.0)
    {
        return Err(MassSpecError::InvalidQuery("fragment parameters require positive charge/match limits and tolerance, correlation in -1..1, and finite non-negative minIntensity".into()));
    }
    Ok(())
}

pub fn modification_deltas(
    sequence: &str,
    modifications: &[MassModification],
) -> Result<(Vec<f64>, f64, f64), MassSpecError> {
    let mut residues = vec![0.0; sequence.len()];
    let mut n_term = 0.0;
    let mut c_term = 0.0;
    for modification in modifications {
        if !modification.delta_mass.is_finite() {
            return Err(MassSpecError::InvalidQuery(
                "modification deltaMass must be finite".to_owned(),
            ));
        }
        match modification.position.as_str() {
            "nTerm" => n_term += modification.delta_mass,
            "cTerm" => c_term += modification.delta_mass,
            value => {
                let position = value.parse::<usize>().map_err(|_| {
                    MassSpecError::InvalidQuery(format!("unknown modification position {value}"))
                })?;
                if position == 0 || position > sequence.len() {
                    return Err(MassSpecError::InvalidQuery(format!(
                        "modification position {position} outside 1..{}",
                        sequence.len()
                    )));
                }
                residues[position - 1] += modification.delta_mass;
            }
        }
    }
    Ok((residues, n_term, c_term))
}

/// Build the theoretical fragment ions for a one-letter sequence with
/// modifications — the `spectrum_utils.get_theoretical_fragments` analogue.
/// Residue masses are computed internally, so callers only supply the
/// sequence and modification list. Positions are 1-based (`"nTerm"`/`"cTerm"`
/// accepted for terminal modifications, matching `modification_deltas`).
pub fn theoretical_fragment_list(
    sequence: &str,
    modifications: &[MassModification],
    ion_types: &[IonType],
    max_charge: u8,
    neutral_losses: &[NamedNeutralLoss],
    engine_losses: bool,
) -> Result<Vec<TheoreticalFragment>, MassSpecError> {
    if sequence.trim().len() < 2 {
        return Err(MassSpecError::InvalidQuery(
            "fragmentTheoretical sequence must contain at least two residues".to_owned(),
        ));
    }
    mzannotate_fragments(
        sequence,
        modifications,
        ion_types,
        max_charge,
        neutral_losses,
        engine_losses,
    )
}

/// Generate theoretical fragments and emit them as a standard **mzPAF** string
/// (HUPO-PSI peak-fragment-annotation format), one fragment per line — the
/// interchange format for fragment annotations, so downstream consumers do not
/// need our JSON schema.
///
/// Uses mzannotate's `ToMzPAF` writer directly on the generated
/// `Fragment<OutputMolecularFormula>` (the mono-isotopic-mass mode is broken in
/// mzcore 0.2.0, see [`mzannotate_fragments`]).
pub fn theoretical_fragments_mzpaf(
    sequence: &str,
    modifications: &[MassModification],
    ion_types: &[IonType],
    max_charge: u8,
) -> Result<String, MassSpecError> {
    let proforma = fragment_proforma(sequence, modifications)?;
    theoretical_fragments_mzpaf_proforma(&proforma, ion_types, max_charge, &[])
}

/// Generate fragments from a normalized HUPO-PSI ProForma expression so
/// TopPIC localization ranges stay in mzcore's peptidoform model.
pub fn theoretical_fragment_list_proforma(
    proforma: &str,
    ion_types: &[IonType],
    max_charge: u8,
    neutral_losses: &[NamedNeutralLoss],
    engine_losses: bool,
) -> Result<Vec<TheoreticalFragment>, MassSpecError> {
    theoretical_fragment_list_proforma_variants(
        &[proforma.to_owned()],
        &[],
        ion_types,
        max_charge,
        neutral_losses,
        engine_losses,
        EnvelopeMode::None,
    )
}

/// Which isotope-shape channel a fragment generation requested.
///
/// The evidence lattice in `docs/design/hypothesis-evidence-lattice.md`:
/// fragment m/z depends only on the summed delta masses, so a mass-only
/// hypothesis is a legal input for ladder/position measurements — but its
/// isotope *shape* cannot be known. `Exact` computes apex + envelope from
/// each fragment's exact composition; `Averagine` substitutes the averagine
/// model of the fragment's mass — an approximation whose neutron-position
/// grid is exact and whose intensities are not a shape claim (the result is
/// labeled `massDelta` by the caller); `None` skips the BRAIN pass (matching
/// hot paths, interchange formats).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EnvelopeMode {
    None,
    Exact,
    Averagine,
}

/// Generate the theoretical fragment ions for ProFormA variants.
/// `EnvelopeMode::Exact` additionally computes each fragment's
/// most-abundant-isotopologue m/z (`TheoreticalFragment::apex_mz` /
/// `apex_offset`) plus the full isotope envelope
/// (`TheoreticalFragment::isotope_envelope`) through the BRAIN kernel —
/// the fragment-level apex anchor for top-down matching where M0 falls below
/// the noise, and the data spectrum viewers need to draw a theoretical isotope
/// stick. Legacy single-peak matching passes `EnvelopeMode::None`; envelope
/// matching and candidate comparison explicitly request `EnvelopeMode::Exact`.
pub fn theoretical_fragment_list_proforma_variants(
    proformas: &[String],
    ambiguous_ranges: &[(usize, usize)],
    ion_types: &[IonType],
    max_charge: u8,
    neutral_losses: &[NamedNeutralLoss],
    engine_losses: bool,
    envelope_mode: EnvelopeMode,
) -> Result<Vec<TheoreticalFragment>, MassSpecError> {
    let mut fragments = Vec::new();
    for proforma in proformas {
        let peptide = parse_fragment_peptidoform(proforma)?;
        fragments.extend(collect_mzannotate_fragments(
            peptide,
            ion_types,
            max_charge,
            neutral_losses,
            engine_losses,
            envelope_mode,
        )?);
    }
    fragments.retain(|fragment| {
        !ambiguous_ranges
            .iter()
            .any(|(start, end)| fragment.cleavage_after >= *start && fragment.cleavage_after < *end)
    });
    sort_dedup_fragments(&mut fragments);
    Ok(fragments)
}

/// mzPAF companion to [`theoretical_fragment_list_proforma`].
pub fn theoretical_fragments_mzpaf_proforma(
    proforma: &str,
    ion_types: &[IonType],
    max_charge: u8,
    neutral_losses: &[NamedNeutralLoss],
) -> Result<String, MassSpecError> {
    theoretical_fragments_mzpaf_proforma_variants(
        &[proforma.to_owned()],
        &[],
        ion_types,
        max_charge,
        neutral_losses,
    )
}

pub fn theoretical_fragments_mzpaf_proforma_variants(
    proformas: &[String],
    ambiguous_ranges: &[(usize, usize)],
    ion_types: &[IonType],
    max_charge: u8,
    neutral_losses: &[NamedNeutralLoss],
) -> Result<String, MassSpecError> {
    if !neutral_losses.is_empty() {
        return Err(MassSpecError::InvalidQuery(
            "custom --neutral-losses are not representable by the mzPAF writer".to_owned(),
        ));
    }
    let mut lines = BTreeSet::new();
    for proforma in proformas {
        let peptide = parse_fragment_peptidoform(proforma)?;
        let generated = peptide.generate_theoretical_fragments::<OutputMolecularFormula>(
            Charge::new::<system::charge::e>(isize::from(max_charge)),
            &fragment_generation_model(),
        );
        for fragment in generated {
            if !fragment.neutral_loss.is_empty() {
                continue;
            }
            let Some((ion, position, variant)) = map_fragment_type(&fragment.ion) else {
                continue;
            };
            let mapped = match (ion, variant) {
                (_, 0) => ion,
                _ => continue,
            };
            let cleavage_after = match mapped {
                IonType::A | IonType::B | IonType::C => position.series_number,
                _ => position
                    .sequence_length
                    .saturating_sub(position.series_number),
            };
            let ambiguous = ambiguous_ranges
                .iter()
                .any(|(start, end)| cleavage_after >= *start && cleavage_after < *end);
            if ion_types.contains(&mapped) && !ambiguous {
                lines.insert(fragment.to_mz_paf_string());
            }
        }
    }
    if lines.is_empty() {
        return Err(MassSpecError::InvalidQuery(
            "mzannotate produced no fragments for this sequence".to_owned(),
        ));
    }
    Ok(lines.into_iter().map(|line| format!("{line}\n")).collect())
}

fn parse_fragment_peptidoform(
    proforma: &str,
) -> Result<mzcore::sequence::Peptidoform<mzcore::sequence::Linear>, MassSpecError> {
    Peptidoform::pro_forma(proforma, &STATIC_ONTOLOGIES)
        .map_err(|errors| {
            let detail = errors
                .iter()
                .map(ToString::to_string)
                .collect::<Vec<_>>()
                .join("; ");
            MassSpecError::InvalidQuery(format!("invalid fragment ProFormA: {detail}"))
        })?
        .0
        .into_linear()
        .ok_or_else(|| MassSpecError::InvalidQuery("fragment ProFormA must be linear".to_owned()))
}

fn mzannotate_fragments(
    sequence: &str,
    modifications: &[MassModification],
    ion_types: &[IonType],
    max_charge: u8,
    neutral_losses: &[NamedNeutralLoss],
    engine_losses: bool,
) -> Result<Vec<TheoreticalFragment>, MassSpecError> {
    let peptide = fragment_peptidoform(sequence, modifications)?;
    collect_mzannotate_fragments(
        peptide,
        ion_types,
        max_charge,
        neutral_losses,
        engine_losses,
        EnvelopeMode::None,
    )
}

/// Canonical memo key for an `ElementCount` list (element, isotope, count).
fn element_counts_key(counts: &[ElementCount]) -> String {
    let mut entries: Vec<(&str, u16, i32)> = counts
        .iter()
        .map(|c| (c.element.as_str(), c.isotope, c.count))
        .collect();
    entries.sort();
    entries
        .iter()
        .map(|(element, isotope, count)| {
            if *isotope != 0 {
                format!("{element}[{isotope}]{count}")
            } else {
                format!("{element}{count}")
            }
        })
        .collect()
}

fn mz_from_neutral_charge(neutral_mass: f64, charge: u8) -> f64 {
    let z = f64::from(charge);
    (neutral_mass + z * PROTON) / z
}

/// Neutral-frame BRAIN isotope envelope for one fragment composition, cached
/// per composition and reused across charge states (the m/z values are
/// charge-dependent, so each fragment re-derives them from this neutral frame).
#[derive(Debug, Clone)]
struct NeutralEnvelope {
    /// (neutron_offset, neutral m/z, apex-normalized relative intensity).
    peaks: Vec<(usize, f64, f64)>,
    /// Index into `peaks` of the most-abundant isotopologue.
    apex_index: usize,
}

/// BRAIN isotope envelope for a composition, computed once and cached by the
/// composition key. `relative_intensity` is normalized to the apex (most
/// abundant isotopologue) = 1.0, so `peaks[apex_index].2 == 1.0` — the
/// convention spectrum viewers use for a theoretical isotope stick.
fn envelope_from_composition(
    counts: &[ElementCount],
    envelope_cache: &mut HashMap<String, NeutralEnvelope>,
) -> NeutralEnvelope {
    let key = element_counts_key(counts);
    if let Some(hit) = envelope_cache.get(&key) {
        return hit.clone();
    }
    let composition = chemical_from_counts(counts);
    let env = theoretical_envelope(&composition, 1, 0.99, 1e-6);
    let apex_index = env
        .peaks
        .iter()
        .enumerate()
        .max_by(|(_, a), (_, b)| a.intensity.total_cmp(&b.intensity))
        .map(|(i, _)| i)
        .unwrap_or(0);
    let apex_intensity = env
        .peaks
        .get(apex_index)
        .map(|peak| peak.intensity)
        .filter(|value| *value > 0.0)
        .unwrap_or(1.0);
    let m0 = env.monoisotopic_neutral;
    // BRAIN emits one peak per neutron, M0 always retained at index 0; a
    // rounded offset guards against any residual spacing drift.
    let peaks: Vec<(usize, f64, f64)> = env
        .center_masses
        .iter()
        .enumerate()
        .map(|(index, neutral_mz)| {
            let neutron_offset = if m0 > 0.0 {
                ((neutral_mz - m0) / 1.003_355).round().max(0.0) as usize
            } else {
                index
            };
            let relative_intensity = env
                .peaks
                .get(index)
                .map(|peak| peak.intensity / apex_intensity)
                .unwrap_or(0.0);
            (neutron_offset, *neutral_mz, relative_intensity)
        })
        .collect();
    let envelope = NeutralEnvelope { peaks, apex_index };
    envelope_cache.insert(key, envelope.clone());
    envelope
}

/// Derive the fragment's charge-frame isotope envelope from the neutral frame.
fn isotope_envelope_from_neutral(
    neutral: &NeutralEnvelope,
    neutral_mass: f64,
    charge: u8,
) -> Vec<IsotopeEnvelopePeak> {
    let m0 = neutral
        .peaks
        .first()
        .map(|peak| peak.1)
        .unwrap_or(neutral_mass);
    neutral
        .peaks
        .iter()
        .map(
            |(neutron_offset, neutral_mz, relative_intensity)| IsotopeEnvelopePeak {
                neutron_offset: *neutron_offset,
                mz: mz_from_neutral_charge(neutral_mass + (neutral_mz - m0), charge),
                relative_intensity: *relative_intensity,
            },
        )
        .collect()
}

fn collect_mzannotate_fragments(
    peptide: mzcore::sequence::Peptidoform<mzcore::sequence::Linear>,
    ion_types: &[IonType],
    max_charge: u8,
    neutral_losses: &[NamedNeutralLoss],
    engine_losses: bool,
    envelope_mode: EnvelopeMode,
) -> Result<Vec<TheoreticalFragment>, MassSpecError> {
    // OutputMolecularFormula (not OutputMonoIsotopic): mzcore 0.2.0's
    // `MassOutput::contains_negative_amount` is inverted (`mass.value >= 0.0`),
    // so the monoisotopic-mass mode `continue`s every normal positive-mass
    // fragment and yields an empty series. MolecularFormula implements the
    // correct semantics, so this mode fragments correctly.
    let generated = peptide.generate_theoretical_fragments::<OutputMolecularFormula>(
        Charge::new::<system::charge::e>(isize::from(max_charge)),
        &fragment_generation_model(),
    );
    let sequence_length = peptide.len();
    // Named losses are modification-defined: parse and range-check their site
    // once, before generation.
    let named_sites: Vec<(usize, LossSite)> = neutral_losses
        .iter()
        .enumerate()
        .map(|(index, loss)| {
            let site = parse_loss_site(loss)?;
            if let LossSite::Residue(position) = site {
                if position > sequence_length {
                    return Err(MassSpecError::InvalidQuery(format!(
                        "neutralLoss position {position} outside sequence 1..{sequence_length}"
                    )));
                }
            }
            Ok((index, site))
        })
        .collect::<Result<_, _>>()?;
    let mut fragments = Vec::new();
    // One BRAIN envelope per composition (neutral frame), reused across the
    // fragment's charge states and across identically-composed fragments.
    let mut envelope_cache: HashMap<String, NeutralEnvelope> = HashMap::new();
    for fragment in generated {
        // Engine-generated loss variants are chemically gated by the engine
        // (series-standard losses plus modification-specific losses from the
        // fragment's own composition). They are emitted only when explicitly
        // requested — recorded no-loss runs must stay reproducible.
        let engine_label = if fragment.neutral_loss.is_empty() {
            None
        } else if engine_losses {
            Some(
                fragment
                    .neutral_loss
                    .iter()
                    .map(|loss| loss.to_string())
                    .collect::<Vec<_>>()
                    .join("+"),
            )
        } else {
            continue;
        };
        let Some((ion, position, variant)) = map_fragment_type(&fragment.ion) else {
            continue;
        };
        let mapped = match (ion, variant) {
            (_, 0) => ion,
            _ => continue,
        };
        if !ion_types.contains(&mapped) {
            continue;
        }
        let charge = u8::try_from(fragment.charge.value).map_err(|_| {
            MassSpecError::InvalidQuery("mzannotate generated an unsupported charge".to_owned())
        })?;
        if charge == 0 || charge > max_charge {
            continue;
        }
        let Some(mz) = fragment.mz(MassMode::Monoisotopic) else {
            continue;
        };
        let mz = mz.value;
        let neutral_mass = mz * f64::from(charge) - PROTON * f64::from(charge);
        // Apex anchor + full isotope envelope.
        let (mut apex_mz, mut apex_offset) = (mz, 0usize);
        let mut isotope_envelope: Vec<IsotopeEnvelopePeak> = Vec::new();
        match envelope_mode {
            EnvelopeMode::None => {}
            EnvelopeMode::Exact => {
                if let Some(counts) = fragment.formula.as_ref().map(formula_to_element_counts) {
                    let neutral = envelope_from_composition(&counts, &mut envelope_cache);
                    apex_offset = neutral.apex_index;
                    isotope_envelope =
                        isotope_envelope_from_neutral(&neutral, neutral_mass, charge);
                }
            }
            EnvelopeMode::Averagine => {
                let counts = crate::proforma::element_counts_from_chemical(
                    &crate::theory::averagine_composition(neutral_mass),
                );
                let neutral = envelope_from_composition(&counts, &mut envelope_cache);
                apex_offset = neutral.apex_index;
                isotope_envelope = isotope_envelope_from_neutral(&neutral, neutral_mass, charge);
            }
        }
        if let Some(apex) = isotope_envelope.get(apex_offset) {
            apex_mz = apex.mz;
            apex_offset = apex.neutron_offset;
        }
        let intact = TheoreticalFragment {
            ion: mapped,
            number: position.series_number,
            charge,
            cleavage_after: match mapped {
                IonType::A | IonType::B | IonType::C => position.series_number,
                _ => position
                    .sequence_length
                    .saturating_sub(position.series_number),
            },
            neutral_mass,
            mz,
            apex_mz,
            apex_offset,
            isotope_envelope: isotope_envelope.clone(),
            neutral_loss: engine_label,
        };
        fragments.push(intact.clone());
        if intact.neutral_loss.is_some() {
            // Engine loss variant: never stack a named loss on top of it.
            continue;
        }
        for (index, site) in &named_sites {
            if !span_contains_site(mapped, position.series_number, sequence_length, *site) {
                continue;
            }
            let loss = &neutral_losses[*index];
            let lost_mass = neutral_mass - loss.delta_mass;
            if lost_mass > 0.0 {
                // A numeric loss has no elemental composition: its envelope
                // is an intact-shape approximation translated in m/z.
                let lost_mz = (lost_mass + f64::from(charge) * PROTON) / f64::from(charge);
                let shift = lost_mz - mz;
                let lost_envelope: Vec<IsotopeEnvelopePeak> = isotope_envelope
                    .iter()
                    .map(|peak| IsotopeEnvelopePeak {
                        neutron_offset: peak.neutron_offset,
                        mz: peak.mz + shift,
                        relative_intensity: peak.relative_intensity,
                    })
                    .collect();
                fragments.push(TheoreticalFragment {
                    neutral_mass: lost_mass,
                    mz: lost_mz,
                    apex_mz: lost_mz + (apex_mz - mz),
                    apex_offset,
                    isotope_envelope: lost_envelope,
                    neutral_loss: Some(loss.label.clone()),
                    ..intact.clone()
                });
            }
        }
    }
    sort_dedup_fragments(&mut fragments);
    Ok(fragments)
}

fn sort_dedup_fragments(fragments: &mut Vec<TheoreticalFragment>) {
    fragments.sort_by(|left, right| {
        left.ion
            .cmp(&right.ion)
            .then(left.number.cmp(&right.number))
            .then(left.charge.cmp(&right.charge))
    });
    fragments.dedup_by(|left, right| {
        left.ion == right.ion
            && left.number == right.number
            && left.charge == right.charge
            && left.neutral_loss == right.neutral_loss
            && (left.mz - right.mz).abs() < 1e-9
    });
}

fn map_fragment_type(
    fragment: &FragmentType,
) -> Option<(IonType, &mzcore::sequence::PeptidePosition, i8)> {
    match fragment {
        FragmentType::a(position, variant) => Some((IonType::A, position, *variant)),
        FragmentType::b(position, variant) => Some((IonType::B, position, *variant)),
        FragmentType::c(position, variant) => Some((IonType::C, position, *variant)),
        FragmentType::x(position, variant) => Some((IonType::X, position, *variant)),
        FragmentType::y(position, variant) => Some((IonType::Y, position, *variant)),
        FragmentType::z(position, variant) => Some((IonType::Z, position, *variant)),
        _ => None,
    }
}

fn fragment_peptidoform(
    sequence: &str,
    modifications: &[MassModification],
) -> Result<mzcore::sequence::Peptidoform<mzcore::sequence::Linear>, MassSpecError> {
    use mzcore::chemistry::MolecularFormula;
    use mzcore::sequence::{
        AminoAcid, Linear, MassTag, SequenceElement, SequencePosition, SimpleModificationInner,
    };
    let sequence = sequence.trim().to_ascii_uppercase();
    modification_deltas(&sequence, modifications)?;
    let residues = sequence
        .chars()
        .map(|residue| {
            if !"ARNDCEQGHILKMFPSTWYV".contains(residue) {
                return Err(MassSpecError::InvalidQuery(format!(
                    "unknown residue {residue}"
                )));
            }
            Ok(SequenceElement::<Linear>::from(
                AminoAcid::try_from(residue).unwrap(),
            ))
        })
        .collect::<Result<Vec<_>, MassSpecError>>()?;
    let mut peptide = Peptidoform::new(residues);
    for modification in modifications {
        let value = if let Some(formula) = &modification.formula {
            let formula = crate::proforma::normalize_formula(formula)?;
            SimpleModificationInner::Formula(
                MolecularFormula::pro_forma::<false, false>(&formula)
                    .map_err(|e| MassSpecError::InvalidQuery(e.to_string()))?,
            )
        } else {
            SimpleModificationInner::Mass(
                MassTag::None,
                mzcore::system::Mass::new::<mzcore::system::dalton>(modification.delta_mass).into(),
                None,
            )
        };
        let site = match modification.position.as_str() {
            "nTerm" => SequencePosition::NTerm,
            "cTerm" => SequencePosition::CTerm,
            position => {
                SequencePosition::Index(position.parse::<usize>().unwrap() - 1, sequence.len())
            }
        };
        peptide.add_simple_modification(site, std::sync::Arc::new(value));
    }
    Ok(peptide)
}

fn fragment_theory(
    query: &FragmentMatchQuery,
) -> Result<(f64, Vec<TheoreticalFragment>), MassSpecError> {
    use mzcore::chemistry::AmbiguousMolecule;
    let peptide = fragment_peptidoform(&query.sequence, &query.modifications)?;
    let mass = peptide
        .calculate_masses_inner::<OutputMolecularFormula>(
            mzcore::sequence::SequencePosition::default(),
            0,
            0,
        )
        .single()
        .ok_or_else(|| MassSpecError::InvalidQuery("ambiguous fragment model composition".into()))?
        .monoisotopic_mass()
        .value;
    let fragments = collect_mzannotate_fragments(
        peptide,
        &query.ion_types,
        query.max_charge,
        &query.neutral_losses,
        query.engine_neutral_losses,
        EnvelopeMode::Exact,
    )?;
    Ok((mass, fragments))
}

fn fragment_proforma(
    sequence: &str,
    modifications: &[MassModification],
) -> Result<String, MassSpecError> {
    Ok(fragment_peptidoform(sequence, modifications)?.to_string())
}

fn error_quantile(matches: &[FragmentMatch], quantile: f64) -> Option<f64> {
    if matches.is_empty() {
        return None;
    }
    let mut values: Vec<f64> = matches.iter().map(|m| m.error_ppm.abs()).collect();
    values.sort_by(f64::total_cmp);
    let index = ((values.len() - 1) as f64 * quantile).round() as usize;
    values.get(index).copied()
}

fn site_window_evidence(
    modifications: &[MassModification],
    matches: &[FragmentMatch],
) -> Vec<SiteWindowEvidence> {
    modifications
        .iter()
        .filter_map(|modification| {
            let position = modification.position.parse::<usize>().ok()?;
            let left_cleavage = position.saturating_sub(1);
            let right_cleavage = position;
            Some(SiteWindowEvidence {
                position,
                left_cleavage,
                right_cleavage,
                matched_left: matches
                    .iter()
                    .filter(|m| m.cleavage_after == left_cleavage)
                    .count(),
                matched_right: matches
                    .iter()
                    .filter(|m| m.cleavage_after == right_cleavage)
                    .count(),
            })
        })
        .collect()
}

fn summarize(
    sequence_length: usize,
    ion_types: &[IonType],
    matches: &[FragmentMatch],
) -> FragmentSummary {
    let backbone_bonds = sequence_length.saturating_sub(1);
    let covered: BTreeSet<_> = matches
        .iter()
        .map(|matched| matched.cleavage_after)
        .collect();
    let mut per_ion_type = BTreeMap::new();
    for ion in ion_types {
        let numbers: BTreeSet<_> = matches
            .iter()
            .filter(|matched| matched.ion == *ion)
            .map(|matched| matched.number)
            .collect();
        let mut longest = 0;
        let mut current = 0;
        let mut previous = None;
        for number in &numbers {
            current = if previous.is_some_and(|value| *number == value + 1) {
                current + 1
            } else {
                1
            };
            longest = longest.max(current);
            previous = Some(*number);
        }
        per_ion_type.insert(
            *ion,
            IonSeriesSummary {
                matched: numbers.len(),
                longest_consecutive_run: longest,
            },
        );
    }
    FragmentSummary {
        backbone_bonds,
        bonds_covered: covered.len(),
        coverage: if backbone_bonds == 0 {
            0.0
        } else {
            covered.len() as f64 / backbone_bonds as f64
        },
        matched_ions: matches.len(),
        // `+ 0.0` normalizes the empty sum's IEEE `-0.0` fold: zero evidence
        // must serialize as one zero shape, not a sign-flipped one.
        matched_intensity: matches
            .iter()
            .map(|matched| f64::from(matched.intensity))
            .sum::<f64>()
            + 0.0,
        per_ion_type,
    }
}

pub(crate) fn residue_mass(residue: char) -> Option<f64> {
    use mzcore::chemistry::AmbiguousMolecule;
    use mzcore::prelude::{AminoAcid, SequencePosition};
    if !"ARNDCEQGHILKMFPSTWYV".contains(residue) {
        return None;
    }
    AminoAcid::try_from(residue)
        .ok()?
        .calculate_masses_inner::<OutputMolecularFormula>(SequencePosition::default(), 0, 0)
        .single()
        .map(|formula| formula.monoisotopic_mass().value)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ion_series_follow_activation_metadata() {
        assert_eq!(
            ion_types_for_activation(Some("ETD")).unwrap(),
            vec![IonType::C, IonType::Z]
        );
        assert_eq!(
            ion_types_for_activation(Some("HCD")).unwrap(),
            vec![IonType::B, IonType::Y]
        );
        assert!(ion_types_for_activation(None).is_err());
    }

    #[test]
    fn msalign_matching_is_charge_aware_and_window_bounded() {
        let make = |mz: f64| TheoreticalFragment {
            ion: IonType::C,
            number: 3,
            charge: 1,
            cleavage_after: 3,
            neutral_mass: mz - PROTON,
            mz,
            apex_mz: mz,
            apex_offset: 0,
            isotope_envelope: Vec::new(),
            neutral_loss: None,
        };
        // one true peak (c3 at charge 1), one same-charge decoy far away,
        // one right-mass wrong-charge decoy
        let peaks = vec![
            crate::localize::DeconvolutedPeak {
                mass: 5000.0,
                intensity: 900.0,
                charge: Some(1),
                score: None,
            },
            crate::localize::DeconvolutedPeak {
                mass: make(500.0).neutral_mass,
                intensity: 700.0,
                charge: Some(1),
                score: None,
            },
            crate::localize::DeconvolutedPeak {
                mass: make(500.0).neutral_mass,
                intensity: 600.0,
                charge: Some(3),
                score: None,
            },
        ];
        let (matches, statuses) =
            match_fragments_msalign(std::slice::from_ref(&make(500.0)), &peaks, 10.0, None);
        assert_eq!(matches.len(), 1, "exactly the true peak matches");
        assert_eq!(matches[0].observed_peak_index, 1);
        assert!(matches[0].error_ppm.abs() < 1e-6);
        assert_eq!(statuses.len(), 0);
        // a theoretical of another charge must NOT take the wrong-charge peak
        let q3 = TheoreticalFragment {
            charge: 3,
            ..make(500.0)
        };
        let (matches, _) = match_fragments_msalign(&[q3], &peaks, 10.0, None);
        assert_eq!(matches.len(), 1);
        assert_eq!(
            matches[0].observed_peak_index, 2,
            "takes its own-charge peak"
        );
    }

    fn drift_match(ion: IonType, number: usize, error_ppm: f64) -> FragmentMatch {
        FragmentMatch {
            ion,
            number,
            charge: 1,
            cleavage_after: number,
            neutral_mass: 1000.0,
            theoretical_mz: 500.0,
            theoretical_apex_mz: 500.0,
            apex_offset: 0,
            observed_isotope_offset: 0,
            observed_mz: 500.0,
            observed_neutral_mass: 1000.0,
            observed_peak_index: 0,
            intensity: 100.0,
            quantification: None,
            envelope_correlation: None,
            error_ppm,
            neutral_loss: None,
        }
    }

    #[test]
    fn series_divergence_stays_silent_for_a_clean_model() {
        // Both series centered at 0 with small spread: no flag.
        let matches: Vec<_> = (1..=8)
            .flat_map(|i| {
                vec![
                    drift_match(IonType::C, i, (i as f64 % 2.0 - 0.5) * 0.2),
                    drift_match(IonType::Z, i, (i as f64 % 3.0 - 1.0) * 0.2),
                ]
            })
            .collect();
        let (per_series, divergence) = series_error_stats(&matches);
        assert_eq!(per_series.len(), 2);
        let divergence = divergence.expect("two populated sides");
        assert!(!divergence.flagged, "{divergence:?}");
    }

    #[test]
    fn series_divergence_flags_a_one_sided_offset() {
        // c ions offset +5 ppm, z ions at 0: the wrong-site signature.
        let matches: Vec<_> = (1..=8)
            .flat_map(|i| {
                vec![
                    drift_match(IonType::C, i, 5.0 + i as f64 * 0.1),
                    drift_match(IonType::Z, i, i as f64 * 0.1 - 0.4),
                ]
            })
            .collect();
        let (_, divergence) = series_error_stats(&matches);
        let divergence = divergence.expect("two populated sides");
        assert!(divergence.flagged, "{divergence:?}");
        assert!(divergence.n_minus_c_ppm > 4.0);
    }

    #[test]
    fn series_divergence_requires_both_sides() {
        // Only c ions: no comparison is possible, so the check is absent.
        let matches: Vec<_> = (1..=10).map(|i| drift_match(IonType::C, i, 9.0)).collect();
        let (_, divergence) = series_error_stats(&matches);
        assert!(divergence.is_none());
    }

    /// A match for a ~5 kDa fragment whose observed peak sits exactly where the
    /// model claims (`error_ppm` relative to its own theory).
    fn borrow_match(
        charge: u8,
        theoretical_mz: f64,
        observed_mz: f64,
        observed_peak_index: usize,
    ) -> FragmentMatch {
        let neutral_mass = (theoretical_mz - PROTON) * f64::from(charge);
        FragmentMatch {
            ion: IonType::Z,
            number: 18,
            charge,
            cleavage_after: 18,
            neutral_mass,
            theoretical_mz,
            theoretical_apex_mz: theoretical_mz,
            apex_offset: 0,
            observed_isotope_offset: 0,
            observed_mz,
            observed_neutral_mass: (observed_mz - PROTON) * f64::from(charge),
            observed_peak_index,
            intensity: 500.0,
            quantification: None,
            envelope_correlation: None,
            error_ppm: (observed_mz - theoretical_mz) / theoretical_mz * 1e6,
            neutral_loss: None,
        }
    }

    fn candidate(id: &str) -> CandidateModel {
        CandidateModel {
            id: id.to_owned(),
            sequence: None,
            modifications: Vec::new(),
        }
    }

    #[test]
    fn isotope_borrow_pairs_flag_integer_neutron_spaced_matches() {
        // Lender explains a 5 kDa fragment at its mono; the borrower's theory
        // sits 2 neutrons + 49 mDa higher (the phospho-vs-bromo geometry) and
        // "matched" the lender's M+2 isotope peak (within 10 ppm of its own
        // theory only because the fragment is large).
        let lender_mz = 5001.007276;
        let observed_lender = lender_mz;
        let observed_borrow = lender_mz + 2.0 * NEUTRON_SHIFT;
        let borrower_mz = lender_mz + 2.0 * NEUTRON_SHIFT + 0.049;
        let models = vec![candidate("lender"), candidate("borrower")];
        let per_candidate = vec![
            vec![borrow_match(1, lender_mz, observed_lender, 3)],
            vec![borrow_match(1, borrower_mz, observed_borrow, 4)],
        ];
        let pairs = detect_isotope_borrow_pairs(&models, &per_candidate, 10.0);
        assert_eq!(pairs.len(), 1, "{pairs:?}");
        let pair = &pairs[0];
        assert_eq!(pair.borrower, "borrower");
        assert_eq!(pair.lender, "lender");
        assert!((pair.neutron_offset - 2.0).abs() < 1e-3, "{pair:?}");
        assert!(pair.residual_ppm.abs() <= 10.0, "{pair:?}");
    }

    #[test]
    fn isotope_borrow_pairs_stay_silent_without_the_signature() {
        let lender_mz = 5001.007276;
        let models = vec![candidate("lender"), candidate("borrower")];
        // Same observed peak = agreement, not borrowing.
        let same_peak = vec![
            vec![borrow_match(1, lender_mz, lender_mz, 3)],
            vec![borrow_match(1, lender_mz + 0.05, lender_mz, 3)],
        ];
        assert!(detect_isotope_borrow_pairs(&models, &same_peak, 10.0).is_empty());
        // Non-integer gap (half a neutron off): random coincidence, silent.
        let half_neutron = vec![
            vec![borrow_match(1, lender_mz, lender_mz, 3)],
            vec![borrow_match(
                1,
                lender_mz + 2.5 * NEUTRON_SHIFT,
                lender_mz + 2.5 * NEUTRON_SHIFT,
                4,
            )],
        ];
        assert!(detect_isotope_borrow_pairs(&models, &half_neutron, 10.0).is_empty());
        // Integer-like offset but the observed-gap residual does not fit the
        // tolerance window (24 ppm on a 5 kDa fragment): silent, because the
        // borrowed peak could not have been matched inside that window at all.
        let wide_residual = vec![
            vec![borrow_match(1, lender_mz, lender_mz, 3)],
            vec![borrow_match(
                1,
                lender_mz + 2.0 * NEUTRON_SHIFT + 0.049,
                lender_mz + 2.0 * NEUTRON_SHIFT + 0.12,
                4,
            )],
        ];
        assert!(detect_isotope_borrow_pairs(&models, &wide_residual, 10.0).is_empty());
        // Inverted assignment (higher-theory model matched BELOW the lender's
        // peak): not borrowing, silent.
        let borrower_mz = lender_mz + 2.0 * NEUTRON_SHIFT + 0.049;
        let inverted = vec![
            vec![borrow_match(
                1,
                lender_mz,
                lender_mz + 2.0 * NEUTRON_SHIFT,
                3,
            )],
            vec![borrow_match(1, borrower_mz, lender_mz, 4)],
        ];
        assert!(detect_isotope_borrow_pairs(&models, &inverted, 10.0).is_empty());
    }

    #[test]
    fn isotope_envelope_invariants_hold_for_a_small_composition() {
        // Glycine (C2H5NO2) — a tiny molecule, so M0 is the apex and the
        // envelope stays in the monoisotopic frame.
        let counts = vec![
            ElementCount {
                element: "C".into(),
                count: 2,
                isotope: 0,
            },
            ElementCount {
                element: "H".into(),
                count: 5,
                isotope: 0,
            },
            ElementCount {
                element: "N".into(),
                count: 1,
                isotope: 0,
            },
            ElementCount {
                element: "O".into(),
                count: 2,
                isotope: 0,
            },
        ];
        let neutral = envelope_from_composition(&counts, &mut HashMap::new());

        // Glycine's M+2 (two 13C) is ~0.03% and truncates away; M0 and M+1
        // must survive. (Large fragments keep far more isotopologues.)
        assert!(neutral.peaks.len() >= 2, "at least M0..M+1 retained");
        let (m0_neutron, _m0_neutral_mz, m0_rel) = neutral.peaks[0];
        assert_eq!(m0_neutron, 0);
        assert!((m0_rel - 1.0).abs() < 1e-9, "M0 is the apex here: {m0_rel}");
        assert_eq!(neutral.apex_index, 0);

        // Neutron offsets are strictly increasing by one.
        for window in neutral.peaks.windows(2) {
            assert_eq!(window[1].0, window[0].0 + 1);
        }
        // m/z spacing is one neutron (in the neutral frame).
        let spacing = neutral.peaks[1].1 - neutral.peaks[0].1;
        assert!((spacing - 1.003_355).abs() < 0.005, "spacing {spacing}");

        // A charge-2 fragment re-derives the same neutral frame shifted up by
        // one proton and halved.
        let env = isotope_envelope_from_neutral(&neutral, neutral.peaks[0].1, 2);
        assert_eq!(env.len(), neutral.peaks.len());
        for (peak, (_, mass, _)) in env.iter().zip(&neutral.peaks) {
            assert!(
                (peak.mz - mz_from_neutral_charge(*mass, 2)).abs() < 1e-9,
                "theory must preserve BRAIN isotope centroids"
            );
        }
        assert!(
            (env[0].mz - (neutral.peaks[0].1 + 2.0 * PROTON) / 2.0).abs() < 1e-6,
            "M0 m/z at z=2"
        );
        assert!((env[0].relative_intensity - 1.0).abs() < 1e-9);
    }

    #[test]
    fn isotope_envelope_apex_anchor_lands_above_m0_for_a_large_fragment() {
        // A large top-down fragment (55 residues, realistic histone c-ion)
        // shifts the most-abundant isotopologue above M0 — the whole point of
        // the apex anchor. The BRAIN envelope must report that offset, and the
        // apex-normalized intensity at that offset must be exactly 1.0.
        let proforma = "SGRGKGGKGLGKGGAKRHRKGGKGLGKGGTGGKAAGAKKGGKARGKGGKAKKGVGGSH".to_owned();
        let fragments = theoretical_fragment_list_proforma_variants(
            &[proforma],
            &[],
            &[IonType::C],
            1,
            &[],
            false,
            EnvelopeMode::Exact,
        )
        .unwrap();
        let big = fragments
            .iter()
            .find(|f| f.ion == IonType::C && f.number == 55)
            .expect("c55 present for the 55-residue sequence");
        assert!(
            big.apex_offset > 0,
            "a large fragment's apex must sit above M0, got offset {}",
            big.apex_offset
        );
        assert!(!big.isotope_envelope.is_empty());
        let apex = &big.isotope_envelope[big.apex_offset];
        assert!(
            (apex.relative_intensity - 1.0).abs() < 1e-9,
            "apex-normalized intensity at the apex must be 1.0"
        );
        // The envelope's M0 must sit at the fragment's monoisotopic m/z.
        assert!(
            (big.isotope_envelope[0].mz - big.mz).abs() < 1e-6,
            "envelope M0 {:.6} vs fragment m/z {:.6}",
            big.isotope_envelope[0].mz,
            big.mz
        );
        // The apex m/z reported on the fragment matches the envelope apex peak.
        assert!(
            (big.apex_mz - apex.mz).abs() < 1e-6,
            "apexMz {:.6} vs envelope apex {:.6}",
            big.apex_mz,
            apex.mz
        );
    }

    #[test]
    fn mass_modification_path_preserves_bromine_isotope_chemistry() {
        // This is the CLI match path: parsed ProForma modifications are
        // carried as MassModification and rebuilt before fragmentation.  The
        // old projection retained only deltaMass, so Br silently became an
        // averagine-like numeric shift and its near-equal M+2 vanished.
        let modifications = vec![MassModification {
            position: "4".to_owned(),
            delta_mass: 77.910_512_542_102,
            formula: Some("BrH-1".to_owned()),
        }];
        let peptide = fragment_peptidoform("PEPY", &modifications).unwrap();
        let fragments = collect_mzannotate_fragments(
            peptide,
            &[IonType::Z],
            1,
            &[],
            false,
            EnvelopeMode::Exact,
        )
        .unwrap();
        let z1 = fragments
            .iter()
            .find(|fragment| fragment.ion == IonType::Z && fragment.number == 1)
            .expect("z1 contains brominated Y4");
        assert!(
            z1.isotope_envelope[2].relative_intensity > 0.7,
            "81Br must make M+2 prominent: {:?}",
            z1.isotope_envelope
        );
    }

    #[test]
    fn envelope_match_reports_informed_mz_error_and_m0_diagnostic() {
        let neutral_mass = 2_000.0;
        let charge = 5;
        let apex_offset = 4;
        let offsets = [0, 2, 3, 4, 5];
        let relative = [0.2, 0.6, 0.9, 1.0, 0.7];
        let isotope_envelope: Vec<_> = relative
            .iter()
            .enumerate()
            .map(|(offset, intensity)| IsotopeEnvelopePeak {
                neutron_offset: offsets[offset],
                mz: mz_from_neutral_charge(
                    neutral_mass + offsets[offset] as f64 * NEUTRON_SHIFT,
                    charge,
                ),
                relative_intensity: *intensity,
            })
            .collect();
        let fragment = TheoreticalFragment {
            ion: IonType::Z,
            number: 20,
            charge,
            cleavage_after: 82,
            neutral_mass,
            mz: mz_from_neutral_charge(neutral_mass, charge),
            apex_mz: isotope_envelope[3].mz,
            apex_offset,
            isotope_envelope: isotope_envelope.clone(),
            neutral_loss: None,
        };
        let observed_neutral_mass = neutral_mass + 0.02; // exactly +10 ppm
        let peaks: Vec<_> = relative
            .iter()
            .enumerate()
            .map(|(offset, intensity)| Peak {
                mz: mz_from_neutral_charge(
                    observed_neutral_mass + offsets[offset] as f64 * NEUTRON_SHIFT,
                    charge,
                ),
                intensity: (*intensity * 1_000.0) as f32,
            })
            .collect();
        let expected_apex_mz = fragment.apex_mz;
        let (matches, statuses) =
            match_fragments_envelope_with_status(&[fragment], &peaks, 20.0, 0.7);
        assert_eq!(matches.len(), 1);
        assert_eq!(statuses.len(), 1);
        assert_eq!(statuses[0].state, FragmentMatchState::Matched);
        assert_eq!(statuses[0].theoretical_apex_mz, expected_apex_mz);
        let matched = &matches[0];
        let signal = matched.quantification.as_ref().unwrap();
        assert!((signal.observed_intensity - 3400.0).abs() < 1e-9);
        assert!((signal.theoretical_fraction - 1.0).abs() < 1e-9);
        assert_eq!(signal.observed_peak_indices, vec![0, 1, 2, 3, 4]);
        assert_eq!(matched.observed_isotope_offset, apex_offset);
        assert!((matched.observed_neutral_mass - observed_neutral_mass).abs() < 1e-9);
        let expected_mz_error =
            (matched.observed_mz - expected_apex_mz) / expected_apex_mz * 1_000_000.0;
        assert!(
            (matched.error_ppm - expected_mz_error).abs() < 1e-9,
            "{matched:?}"
        );
        assert!(
            matched.envelope_correlation.unwrap() > 0.999_999,
            "{matched:?}"
        );
    }

    #[test]
    fn bare_scan_id_resolves_to_controller_prefixed_native_id() {
        // The GAV fixture uses plain `scan=2`; wrap it in a controller-prefixed
        // id to exercise the `scan=<N>` suffix resolution used by real Thermo
        // data (`controllerType=0 controllerNumber=1 scan=1164`).
        let xml = std::fs::read(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/fixtures/fragment-match-gav.mzML"
        ))
        .unwrap();
        let mut reader = open_reader(&xml).unwrap();
        let selector = SpectrumSelector::Id("scan=2".to_owned());
        // The fixture has no controller prefix, so resolution must fall back to
        // the exact id — matching the plain `scan=2` spectrum.
        let resolved = resolve_selector(&xml, &selector).unwrap();
        assert_eq!(resolved, SpectrumSelector::Id("scan=2".to_owned()));
        assert!(reader
            .get_spectrum_by_id(match &resolved {
                SpectrumSelector::Id(id) => id,
                _ => unreachable!(),
            })
            .is_some());

        // A scan number that exists nowhere must still resolve to the same
        // selector so the caller surfaces the standard SpectrumNotFound error.
        let missing =
            resolve_selector(&xml, &SpectrumSelector::Id("scan=9999".to_owned())).unwrap();
        assert_eq!(missing, SpectrumSelector::Id("scan=9999".to_owned()));
    }
}
